    private static float TaMask(float s, int r, int pos, int t0, int cnt, ArrayView<int> tokInfo, float softCap)
    {
        if (r >= cnt) return float.NegativeInfinity;
        int start = tokInfo[3 * (t0 + r) + 1], end = tokInfo[3 * (t0 + r) + 2];
        if (pos < start || pos > end) return float.NegativeInfinity;
        return softCap > 0 ? Tanh(s / softCap) * softCap : s;
    }

    private static void TaStore(ArrayView<float> q, ArrayView<float> outp, AttnParams p, int t0, int cnt, int h, int r, int d, float v0, float v1)
    {
        if (r >= cnt) return;
        long oo = p.OutOff + (long)(t0 + r) * p.OutStride + (long)h * p.HdV + d;
        if (p.Gated != 0)
        {
            long go = p.QOff + (long)(t0 + r) * p.QStride + (long)h * p.QHeadPitch + p.Hd + d;
            v0 *= Sigmoid(q[go]); v1 *= Sigmoid(q[go + 1]);
        }
        outp[oo] = v0;
        outp[oo + 1] = v1;
    }
